const int delta_y[4] = {1, -1, 0, 0};
char maze[N][N], S[N][N];
int i, j, start_x, start_y, source, sink, n, t, total, id[N][N], dist[N][N], visited[N][N], queue[M], head[N*N*2], tail[N*N*2];
