    for (i = head[node]; i && flow; i = edges[i].prev)
        if (edges[i].flow > 0 && dist[edges[i].to] == dist[node] + 1)
            if (a = dfs(edges[i].to, min(edges[i].flow, flow)))
            {
                edges[i].flow -= a;
                edges[i ^ 1].flow += a;
                flow -= a;
                total_flow += a;
            }
    if (!total_flow) dist[node] = 1000000000;
    return total_flow;
}

int max_flow()
{
    int total_flow = 0, flow;
    while (bfs())
    {
        flow = dfs(source, 1000000000);
        while (flow)
        {
            total_flow += flow;
            flow = dfs(source, 1000000000);
        }
    }
    return total_flow;
