                Dis[ax + delta_x[i]][ay + delta_y[i]] = Dis[ax][ay] + 1;
                visited[ax + delta_x[i]][ay + delta_y[i]] = 1;
                if (Dis[ax + delta_x[i]][ay + delta_y[i]] < dist[ax + delta_x[i]][ay + delta_y[i]])
